    let v2FP16 = Vector512FP16(from: v2)

    var timings: [Double] = []
    let runs = 20
    let opsPerRun = 1000

    for _ in 0..<runs {
        let start = Date()
        var result: Float = 0

        for _ in 0..<opsPerRun {
            let fp32_1 = v1FP16.toFP32()
            let fp32_2 = v2FP16.toFP32()
